/* Waqiyat-e-Ambiya — batch 4: Hazrat Yusuf (AS). Surah Yusuf + sahih ahadees. */
(function(){
var S=(window.TABLIGH||[]).find(function(s){return s.id==="ambiya";}); if(!S) return;
S.ch.push(
{ro:"Hazrat Yusuf (AS) — Hissa 1: Kuan, fitna aur qaid", ur:"حضرت یوسف علیہ السلام — حصہ ١: کنواں، فتنہ اور قید", b:[
 ["p","Hazrat Yusuf (AS) ka qissa Quran ka woh qissa hai jise Allah ne khud 'Ahsan-ul-Qasas' — sab se behtareen qissa — kaha. Quran mein baaki Ambiya ke qisse alag alag surahon mein tukdon mein aaye hain, lekin Yusuf (AS) ka poora qissa shuru se aakhir tak ek hi surah — Surah Yusuf — mein tarteeb se bayan hua hai. Is mein hasad bhi hai, sabr bhi, fitna bhi, paakdamani bhi, qaid bhi, izzat bhi, aur aakhir mein maafi ka woh manzar jo dilon ko pighla deta hai.","حضرت یوسف علیہ السلام کا قصہ قرآن کا وہ قصہ ہے جسے اللہ نے خود 'احسن القصص' — سب سے بہترین قصہ — کہا۔ قرآن میں باقی انبیاء کے قصے الگ الگ سورتوں میں ٹکڑوں میں آئے ہیں، لیکن یوسف علیہ السلام کا پورا قصہ شروع سے آخر تک ایک ہی سورت — سورۂ یوسف — میں ترتیب سے بیان ہوا ہے۔ اس میں حسد بھی ہے، صبر بھی، فتنہ بھی، پاکدامنی بھی، قید بھی، عزت بھی، اور آخر میں معافی کا وہ منظر جو دلوں کو پگھلا دیتا ہے۔"],
 ["v","12:3","Hum aap ko is Quran ki wahi ke zariye sab se behtareen qissa sunaate hain, aur is se pehle aap (in baaton se) be-khabar the.","ہم آپ کو اس قرآن کی وحی کے ذریعے سب سے بہترین قصہ سناتے ہیں، اور اس سے پہلے آپ (ان باتوں سے) بے خبر تھے۔"],
 ["p","Yeh surah Makka mein us waqt naazil hui jab Nabi ﷺ par sab se mushkil daur tha — Hazrat Khadija (RA) aur Abu Talib ka inteqaal ho chuka tha, aur Quraish ki takleefein badh gayi thin. Is qisse mein Nabi ﷺ aur Sahaba ke liye tasalli thi: jis tarah Yusuf (AS) ko bhaiyon ne nikaala aur phir woh izzat se lautey, isi tarah aapko bhi Makka se nikaala jaayega aur aap fateh ke saath wapas aayenge.","یہ سورت مکہ میں اس وقت نازل ہوئی جب نبی ﷺ پر سب سے مشکل دور تھا — حضرت خدیجہؓ اور ابو طالب کا انتقال ہو چکا تھا، اور قریش کی تکلیفیں بڑھ گئی تھیں۔ اس قصے میں نبی ﷺ اور صحابہ کے لیے تسلی تھی: جس طرح یوسف علیہ السلام کو بھائیوں نے نکالا اور پھر وہ عزت سے لوٹے، اسی طرح آپ کو بھی مکہ سے نکالا جائے گا اور آپ فتح کے ساتھ واپس آئیں گے۔"],

 ["h","Khwab — gyarah sitare, suraj aur chaand","خواب — گیارہ ستارے، سورج اور چاند"],
 ["p","Yusuf (AS) chhote the. Ek din apne waalid Hazrat Yaqub (AS) se kaha: abba jaan! main ne khwab mein gyarah sitare, suraj aur chaand dekhe — main ne dekha ki woh mujhe sajda kar rahe hain. Yaqub (AS) samajh gaye ki yeh bete ke liye bade maqaam ki nishaani hai. Lekin unhein yeh bhi maaloom tha ki Yusuf ke sauteile bhai unse jalte hain. Farmaya: beta! apna yeh khwab apne bhaiyon ko na batana, warna woh tumhare khilaf koi chaal chalenge; shaitan insaan ka khula dushman hai.","یوسف علیہ السلام چھوٹے تھے۔ ایک دن اپنے والد حضرت یعقوب علیہ السلام سے کہا: ابا جان! میں نے خواب میں گیارہ ستارے، سورج اور چاند دیکھے — میں نے دیکھا کہ وہ مجھے سجدہ کر رہے ہیں۔ یعقوب علیہ السلام سمجھ گئے کہ یہ بیٹے کے لیے بڑے مقام کی نشانی ہے۔ لیکن انہیں یہ بھی معلوم تھا کہ یوسف کے سوتیلے بھائی ان سے جلتے ہیں۔ فرمایا: بیٹا! اپنا یہ خواب اپنے بھائیوں کو نہ بتانا، ورنہ وہ تمہارے خلاف کوئی چال چلیں گے؛ شیطان انسان کا کھلا دشمن ہے۔"],
 ["v","12:4-6","Jab Yusuf ne apne baap se kaha: abba jaan! main ne (khwab mein) gyarah sitare aur suraj aur chaand dekhe, main ne unhein dekha ki mujhe sajda kar rahe hain. (Baap ne) kaha: beta! apna khwab apne bhaiyon ko na sunana, warna woh tumhare khilaf chaal chalenge; beshak shaitan insaan ka khula dushman hai. Aur isi tarah tumhara Rab tumhein chun lega, aur tumhein baaton ki haqeeqat (khwabon ki ta'beer) sikhayega, aur tum par aur Aal-e-Yaqub par apni ne'mat poori karega, jaise is se pehle tumhare baap dada Ibrahim aur Ishaq par poori kar chuka hai…","جب یوسف نے اپنے باپ سے کہا: ابا جان! میں نے (خواب میں) گیارہ ستارے اور سورج اور چاند دیکھے، میں نے انہیں دیکھا کہ مجھے سجدہ کر رہے ہیں۔ (باپ نے) کہا: بیٹا! اپنا خواب اپنے بھائیوں کو نہ سنانا، ورنہ وہ تمہارے خلاف چال چلیں گے؛ بے شک شیطان انسان کا کھلا دشمن ہے۔ اور اسی طرح تمہارا رب تمہیں چن لے گا، اور تمہیں باتوں کی حقیقت (خوابوں کی تعبیر) سکھائے گا، اور تم پر اور آلِ یعقوب پر اپنی نعمت پوری کرے گا، جیسے اس سے پہلے تمہارے باپ دادا ابراہیم اور اسحاق پر پوری کر چکا ہے…"],
 ["p","Yahan pehla sabaq hai: har ne'mat har kisi ko batana zaroori nahi. Nabi ﷺ ne bhi farmaya ki achha khwab sirf usi ko batao jisse muhabbat ho. Hasad karne walon se apni ne'maton ko chhupaana hikmat hai.","یہاں پہلا سبق ہے: ہر نعمت ہر کسی کو بتانا ضروری نہیں۔ نبی ﷺ نے بھی فرمایا کہ اچھا خواب صرف اسی کو بتاؤ جس سے محبت ہو۔ حسد کرنے والوں سے اپنی نعمتوں کو چھپانا حکمت ہے۔"],
 ["n","'Achha khwab sirf pyaare ko batao' — Sahih Bukhari aur Sahih Muslim.","'اچھا خواب صرف پیارے کو بتاؤ' — صحیح بخاری اور صحیح مسلم۔"],

 ["h","Bhaiyon ka hasad aur saazish","بھائیوں کا حسد اور سازش"],
 ["p","Yaqub (AS) ke baara bete the. Yusuf (AS) aur unke chhote bhai Bin-Yameen ek maa se the, baaqi das bhai doosri maaon se. Yaqub (AS) ko Yusuf se khaas muhabbat thi — unki nek-fitri aur woh nishaaniyan dekh kar jo unmein thin. Bade bhai is par jalte the. Unhone aapas mein mashwara kiya: Yusuf aur uska bhai abba ko hum se zyada pyaare hain, halaanki hum taqatwar jamaat hain. Yusuf ko maar daalo ya kisi door jagah phenk do, taaki abba ki tawajjoh sirf hamari taraf ho jaaye — phir baad mein nek ban jaana!","یعقوب علیہ السلام کے بارہ بیٹے تھے۔ یوسف علیہ السلام اور ان کے چھوٹے بھائی بن یامین ایک ماں سے تھے، باقی دس بھائی دوسری ماؤں سے۔ یعقوب علیہ السلام کو یوسف سے خاص محبت تھی — ان کی نیک فطرتی اور وہ نشانیاں دیکھ کر جو ان میں تھیں۔ بڑے بھائی اس پر جلتے تھے۔ انہوں نے آپس میں مشورہ کیا: یوسف اور اس کا بھائی ابا کو ہم سے زیادہ پیارے ہیں، حالانکہ ہم طاقتور جماعت ہیں۔ یوسف کو مار ڈالو یا کسی دور جگہ پھینک دو، تاکہ ابا کی توجہ صرف ہماری طرف ہو جائے — پھر بعد میں نیک بن جانا!"],
 ["v","12:8-10","Jab unhone (aapas mein) kaha: Yusuf aur uska bhai hamare baap ko hum se zyada pyaare hain, halaanki hum ek mazboot jamaat hain; beshak hamare baap khuli ghalti par hain. Yusuf ko qatl kar do ya use kisi zameen mein phenk aao, taaki tumhare baap ki tawajjoh sirf tumhari taraf ho jaaye, aur uske baad tum nek log ban jaana. Un mein se ek kehne wale ne kaha: Yusuf ko qatl na karo, balki agar tumhein kuch karna hi hai to use kisi andhe kuein ki tah mein daal do, koi raah chalta qaafila use utha le jaayega.","جب انہوں نے (آپس میں) کہا: یوسف اور اس کا بھائی ہمارے باپ کو ہم سے زیادہ پیارے ہیں، حالانکہ ہم ایک مضبوط جماعت ہیں؛ بے شک ہمارے باپ کھلی غلطی پر ہیں۔ یوسف کو قتل کر دو یا اسے کسی زمین میں پھینک آؤ، تاکہ تمہارے باپ کی توجہ صرف تمہاری طرف ہو جائے، اور اس کے بعد تم نیک لوگ بن جانا۔ ان میں سے ایک کہنے والے نے کہا: یوسف کو قتل نہ کرو، بلکہ اگر تمہیں کچھ کرنا ہی ہے تو اسے کسی اندھے کنویں کی تہ میں ڈال دو، کوئی راہ چلتا قافلہ اسے اٹھا لے جائے گا۔"],
 ["p","Shaitan ka sab se khatarnaak dhoka dekhiye: 'abhi gunah kar lo, baad mein nek ban jaana'. Kitne log isi dhoke mein zindagi guzaar dete hain.","شیطان کا سب سے خطرناک دھوکا دیکھیے: 'ابھی گناہ کر لو، بعد میں نیک بن جانا'۔ کتنے لوگ اسی دھوکے میں زندگی گزار دیتے ہیں۔"],

 ["h","Kuan aur jhoota khoon","کنواں اور جھوٹا خون"],
 ["p","Bhaiyon ne baap se kaha: abba! aap Yusuf ke baare mein hum par bharosa kyun nahi karte? Kal use hamare saath bhej dijiye, khelega koodega, hum uski hifazat karenge. Yaqub (AS) ne farmaya: mujhe dar hai ki tum us se ghaafil ho jaao aur use bhediya kha jaaye. Bhaiyon ne kaha: hum itni badi jamaat hain, agar bhediya kha gaya to hum bilkul nikamme thehre! Aakhir Yusuf (AS) ko le gaye aur kuein mein daal diya. Usi waqt Allah ne Yusuf (AS) ko wahi ki: ek din tum inhein inka yeh kaam jataaoge aur inhein khabar bhi na hogi.","بھائیوں نے باپ سے کہا: ابا! آپ یوسف کے بارے میں ہم پر بھروسہ کیوں نہیں کرتے؟ کل اسے ہمارے ساتھ بھیج دیجیے، کھیلے گا کودے گا، ہم اس کی حفاظت کریں گے۔ یعقوب علیہ السلام نے فرمایا: مجھے ڈر ہے کہ تم اس سے غافل ہو جاؤ اور اسے بھیڑیا کھا جائے۔ بھائیوں نے کہا: ہم اتنی بڑی جماعت ہیں، اگر بھیڑیا کھا گیا تو ہم بالکل نکمے ٹھہرے! آخر یوسف علیہ السلام کو لے گئے اور کنویں میں ڈال دیا۔ اسی وقت اللہ نے یوسف علیہ السلام کو وحی کی: ایک دن تم انہیں ان کا یہ کام جتاؤ گے اور انہیں خبر بھی نہ ہوگی۔"],
 ["v","12:15","Phir jab woh use le gaye aur sab ne milkar tay kar liya ki use andhe kuein ki tah mein daal dein, (aur daal diya) to humne Yusuf ki taraf wahi ki: tum zaroor (ek din) inhein inka yeh kaam jataaoge aur inhein khabar bhi na hogi.","پھر جب وہ اسے لے گئے اور سب نے مل کر طے کر لیا کہ اسے اندھے کنویں کی تہ میں ڈال دیں، (اور ڈال دیا) تو ہم نے یوسف کی طرف وحی کی: تم ضرور (ایک دن) انہیں ان کا یہ کام جتاؤ گے اور انہیں خبر بھی نہ ہوگی۔"],
 ["p","Raat ko rote hue baap ke paas aaye: abba! hum daud ka muqabla karne gaye aur Yusuf ko saamaan ke paas chhod diya, to use bhediya kha gaya. Aap to hamari baat maanenge nahi, chahe hum sacche hon. Aur Yusuf ki qameez par jhoota khoon laga kar le aaye. Lekin qameez phati nahi thi — bhediya kha gaya aur kurta saalim! Yaqub (AS) samajh gaye. Farmaya: balki tumhare nafs ne tumhare liye ek baat bana li hai. Ab sabr hi behtar hai — Sabr-e-Jameel — aur jo tum bayan karte ho us par Allah hi se madad maangi jaati hai.","رات کو روتے ہوئے باپ کے پاس آئے: ابا! ہم دوڑ کا مقابلہ کرنے گئے اور یوسف کو سامان کے پاس چھوڑ دیا، تو اسے بھیڑیا کھا گیا۔ آپ تو ہماری بات مانیں گے نہیں، چاہے ہم سچے ہوں۔ اور یوسف کی قمیص پر جھوٹا خون لگا کر لے آئے۔ لیکن قمیص پھٹی نہیں تھی — بھیڑیا کھا گیا اور کرتا سالم! یعقوب علیہ السلام سمجھ گئے۔ فرمایا: بلکہ تمہارے نفس نے تمہارے لیے ایک بات بنا لی ہے۔ اب صبر ہی بہتر ہے — صبرِ جمیل — اور جو تم بیان کرتے ہو اس پر اللہ ہی سے مدد مانگی جاتی ہے۔"],
 ["v","12:16-18","Aur woh shaam ko rote hue apne baap ke paas aaye. Kehne lage: abba jaan! hum aapas mein daud lagaane chale gaye aur Yusuf ko apne saamaan ke paas chhod diya, to use bhediya kha gaya; aur aap hamari baat ka yaqeen nahi karenge chahe hum sacche hon. Aur woh uski qameez par jhoota khoon laga laaye. (Yaqub ne) kaha: (nahi) balki tumhare nafs ne tumhare liye ek baat bana di hai; to sabr hi achha hai, aur jo kuch tum bayan karte ho us par Allah hi se madad maangi jaati hai.","اور وہ شام کو روتے ہوئے اپنے باپ کے پاس آئے۔ کہنے لگے: ابا جان! ہم آپس میں دوڑ لگانے چلے گئے اور یوسف کو اپنے سامان کے پاس چھوڑ دیا، تو اسے بھیڑیا کھا گیا؛ اور آپ ہماری بات کا یقین نہیں کریں گے چاہے ہم سچے ہوں۔ اور وہ اس کی قمیص پر جھوٹا خون لگا لائے۔ (یعقوب نے) کہا: (نہیں) بلکہ تمہارے نفس نے تمہارے لیے ایک بات بنا دی ہے؛ تو صبر ہی اچھا ہے، اور جو کچھ تم بیان کرتے ہو اس پر اللہ ہی سے مدد مانگی جاتی ہے۔"],
 ["p","'Sabr-e-Jameel' kya hai? Ulama farmate hain: woh sabr jismein makhlooq se shikayat na ho. Dil roye, aankh roye, magar zabaan par Allah ke faisle ke khilaf koi lafz na aaye, aur shikayat sirf Allah se ho.","'صبرِ جمیل' کیا ہے؟ علماء فرماتے ہیں: وہ صبر جس میں مخلوق سے شکایت نہ ہو۔ دل روئے، آنکھ روئے، مگر زبان پر اللہ کے فیصلے کے خلاف کوئی لفظ نہ آئے، اور شکایت صرف اللہ سے ہو۔"],

 ["h","Qaafila aur Misr ka bazaar","قافلہ اور مصر کا بازار"],
 ["p","Ek qaafila wahan se guzra. Unhone paani ke liye apna aadmi bheja, usne kuein mein dol daala — aur dol ke saath ek khoobsurat ladka nikal aaya! Woh pukaar utha: khushkhabri! yeh to ek ladka hai! Qaafile walon ne use tijarat ka maal samajh kar chhupa liya aur Misr le ja kar chand dirhamon mein bech diya — kyunki unhein us ki qadar hi na thi. Sochiye: jise Allah Misr ka hakim banane wala tha, use koudiyon ke mol bech diya gaya.","ایک قافلہ وہاں سے گزرا۔ انہوں نے پانی کے لیے اپنا آدمی بھیجا، اس نے کنویں میں ڈول ڈالا — اور ڈول کے ساتھ ایک خوبصورت لڑکا نکل آیا! وہ پکار اٹھا: خوشخبری! یہ تو ایک لڑکا ہے! قافلے والوں نے اسے تجارت کا مال سمجھ کر چھپا لیا اور مصر لے جا کر چند درہموں میں بیچ دیا — کیونکہ انہیں اس کی قدر ہی نہ تھی۔ سوچیے: جسے اللہ مصر کا حاکم بنانے والا تھا، اسے کوڑیوں کے مول بیچ دیا گیا۔"],
 ["v","12:19-20","Aur ek qaafila aaya, to unhone apna paani laane wala bheja, usne apna dol daala; (aur) kaha: khushkhabri! yeh to ek ladka hai! Aur unhone use tijarat ka maal samajh kar chhupa liya, aur Allah khoob jaanta tha jo woh karte the. Aur unhone use thodi si qeemat — gine chune chand dirhamon — mein bech diya, aur woh us mein be-raghbat the.","اور ایک قافلہ آیا، تو انہوں نے اپنا پانی لانے والا بھیجا، اس نے اپنا ڈول ڈالا؛ (اور) کہا: خوشخبری! یہ تو ایک لڑکا ہے! اور انہوں نے اسے تجارت کا مال سمجھ کر چھپا لیا، اور اللہ خوب جانتا تھا جو وہ کرتے تھے۔ اور انہوں نے اسے تھوڑی سی قیمت — گنے چنے چند درہموں — میں بیچ دیا، اور وہ اس میں بے رغبت تھے۔"],
 ["h","Azeez-e-Misr ka ghar","عزیزِ مصر کا گھر"],
 ["p","Misr mein unhein ek bade sardar ne khareeda jise Quran 'Al-Azeez' kehta hai (yaani wazeer ya bada afsar). Usne apni biwi se kaha: ise izzat se rakhna, shayad yeh hamare kaam aaye ya hum ise beta bana lein. Yun Allah ne Yusuf (AS) ko kuein ki tah se utha kar Misr ke sab se bade ghar mein pahuncha diya. Allah apne kaam par ghaalib hai, magar aksar log nahi jaante.","مصر میں انہیں ایک بڑے سردار نے خریدا جسے قرآن 'العزیز' کہتا ہے (یعنی وزیر یا بڑا افسر)۔ اس نے اپنی بیوی سے کہا: اسے عزت سے رکھنا، شاید یہ ہمارے کام آئے یا ہم اسے بیٹا بنا لیں۔ یوں اللہ نے یوسف علیہ السلام کو کنویں کی تہ سے اٹھا کر مصر کے سب سے بڑے گھر میں پہنچا دیا۔ اللہ اپنے کام پر غالب ہے، مگر اکثر لوگ نہیں جانتے۔"],
 ["v","12:21-22","Aur Misr ke jis shakhs ne use khareeda usne apni biwi se kaha: ise izzat se rakho, shayad yeh hamein faayda de ya hum ise beta bana lein. Aur isi tarah humne Yusuf ko us sarzameen mein jagah di, aur taaki hum use baaton ki haqeeqat sikhaayein; aur Allah apne kaam par ghaalib hai, lekin aksar log nahi jaante. Aur jab woh apni jawani ko pahunche to humne unhein hikmat aur ilm ata kiya; aur hum nekokaron ko aisa hi badla dete hain.","اور مصر کے جس شخص نے اسے خریدا اس نے اپنی بیوی سے کہا: اسے عزت سے رکھو، شاید یہ ہمیں فائدہ دے یا ہم اسے بیٹا بنا لیں۔ اور اسی طرح ہم نے یوسف کو اس سرزمین میں جگہ دی، اور تاکہ ہم اسے باتوں کی حقیقت سکھائیں؛ اور اللہ اپنے کام پر غالب ہے، لیکن اکثر لوگ نہیں جانتے۔ اور جب وہ اپنی جوانی کو پہنچے تو ہم نے انہیں حکمت اور علم عطا کیا؛ اور ہم نیکوکاروں کو ایسا ہی بدلہ دیتے ہیں۔"],

 ["h","Sab se bada imtihaan — paakdamani","سب سے بڑا امتحان — پاکدامنی"],
 ["p","Yusuf (AS) jawan hue. Allah ne unhein be-misaal husn diya tha — Nabi ﷺ ne Me'raj ki raat unhein dekha aur farmaya ki unhein husn ka aadha hissa diya gaya tha. Azeez ki biwi unpar fareefta ho gayi. Ek din usne saare darwaze band kar diye aur kaha: aao! Yusuf (AS) ne foran kaha: Ma'aazAllah — Allah ki panaah! woh (tumhara shauhar) mera maalik hai, usne mujhe achhi tarah rakha; zaalim kabhi kaamyaab nahi hote.","یوسف علیہ السلام جوان ہوئے۔ اللہ نے انہیں بے مثال حسن دیا تھا — نبی ﷺ نے معراج کی رات انہیں دیکھا اور فرمایا کہ انہیں حسن کا آدھا حصہ دیا گیا تھا۔ عزیز کی بیوی ان پر فریفتہ ہو گئی۔ ایک دن اس نے سارے دروازے بند کر دیے اور کہا: آؤ! یوسف علیہ السلام نے فوراً کہا: معاذ اللہ — اللہ کی پناہ! وہ (تمہارا شوہر) میرا مالک ہے، اس نے مجھے اچھی طرح رکھا؛ ظالم کبھی کامیاب نہیں ہوتے۔"],
 ["v","12:23-24","Aur jis aurat ke ghar mein woh the usne unhein unke nafs ke baare mein phuslaya, aur darwaze band kar diye, aur kaha: aao! (Yusuf ne) kaha: Allah ki panaah! woh mera maalik hai, usne mujhe achhi tarah rakha; beshak zaalim kaamyaab nahi hote. Aur us aurat ne unka iraada kar liya, aur woh bhi uska iraada kar lete agar apne Rab ki daleel na dekh lete. Isi tarah (hua) taaki hum un se buraai aur be-hayaai ko door rakhein; beshak woh hamare chune hue bandon mein se the.","اور جس عورت کے گھر میں وہ تھے اس نے انہیں ان کے نفس کے بارے میں پھسلایا، اور دروازے بند کر دیے، اور کہا: آؤ! (یوسف نے) کہا: اللہ کی پناہ! وہ میرا مالک ہے، اس نے مجھے اچھی طرح رکھا؛ بے شک ظالم کامیاب نہیں ہوتے۔ اور اس عورت نے ان کا ارادہ کر لیا، اور وہ بھی اس کا ارادہ کر لیتے اگر اپنے رب کی دلیل نہ دیکھ لیتے۔ اسی طرح (ہوا) تاکہ ہم ان سے برائی اور بے حیائی کو دور رکھیں؛ بے شک وہ ہمارے چنے ہوئے بندوں میں سے تھے۔"],
 ["p","Sochiye halaat: jawan, ghar se door, ghulam, koi dekhne wala nahi, darwaze band, aur khud maalkin bula rahi hai. Phir bhi Yusuf (AS) ne 'Ma'aazAllah' kaha aur darwaze ki taraf bhaage. Yahi woh shakhs hai jiske baare mein Nabi ﷺ ne farmaya ki qayamat ke din Allah ke arsh ka saaya paane walon mein woh bhi hoga jise ek izzat wali, khoobsurat aurat ne bulaya aur usne kaha: main Allah se darta hoon.","سوچیے حالات: جوان، گھر سے دور، غلام، کوئی دیکھنے والا نہیں، دروازے بند، اور خود مالکن بلا رہی ہے۔ پھر بھی یوسف علیہ السلام نے 'معاذ اللہ' کہا اور دروازے کی طرف بھاگے۔ یہی وہ شخص ہے جس کے بارے میں نبی ﷺ نے فرمایا کہ قیامت کے دن اللہ کے عرش کا سایہ پانے والوں میں وہ بھی ہوگا جسے ایک عزت والی، خوبصورت عورت نے بلایا اور اس نے کہا: میں اللہ سے ڈرتا ہوں۔"],
 ["n","'Husn ka aadha hissa' — Sahih Muslim (hadees-e-Me'raj). 'Saat log arsh ke saaye mein' — Sahih Bukhari aur Sahih Muslim. Quran ne Azeez ki biwi ka naam nahi liya; 'Zulaikha' naam aur Yusuf (AS) se baad mein uske nikah ki kahani Israiliyat se hai, sahih daleel se saabit nahi.","'حسن کا آدھا حصہ' — صحیح مسلم (حدیثِ معراج)۔ 'سات لوگ عرش کے سائے میں' — صحیح بخاری اور صحیح مسلم۔ قرآن نے عزیز کی بیوی کا نام نہیں لیا؛ 'زلیخا' نام اور یوسف علیہ السلام سے بعد میں اس کے نکاح کی کہانی اسرائیلیات سے ہے، صحیح دلیل سے ثابت نہیں۔"],
 ["h","Peeche se phati qameez","پیچھے سے پھٹی قمیص"],
 ["p","Yusuf (AS) darwaze ki taraf bhaage, woh peeche daudi aur unki qameez peeche se kheench kar phaad di. Darwaze par hi Azeez saamne aa gaya. Aurat ne foran ilzaam laga diya: jo tumhari biwi ke saath bura iraada kare uski saza qaid ya dardnaak azaab ke siwa kya hai? Yusuf (AS) ne kaha: isi ne mujhe phuslaya tha. Ghar walon mein se ek gawah ne faisla kiya: agar qameez aage se phati hai to aurat sacchi hai; agar peeche se phati hai to aurat jhooti hai. Qameez peeche se phati thi. Azeez ne kaha: yeh tum auraton ki chaal hai, aur tumhari chaalein badi sakht hain. Yusuf! is baat ko jaane do; aur tum (aurat) apne gunah ki maafi maango.","یوسف علیہ السلام دروازے کی طرف بھاگے، وہ پیچھے دوڑی اور ان کی قمیص پیچھے سے کھینچ کر پھاڑ دی۔ دروازے پر ہی عزیز سامنے آ گیا۔ عورت نے فوراً الزام لگا دیا: جو تمہاری بیوی کے ساتھ برا ارادہ کرے اس کی سزا قید یا دردناک عذاب کے سوا کیا ہے؟ یوسف علیہ السلام نے کہا: اسی نے مجھے پھسلایا تھا۔ گھر والوں میں سے ایک گواہ نے فیصلہ کیا: اگر قمیص آگے سے پھٹی ہے تو عورت سچی ہے؛ اگر پیچھے سے پھٹی ہے تو عورت جھوٹی ہے۔ قمیص پیچھے سے پھٹی تھی۔ عزیز نے کہا: یہ تم عورتوں کی چال ہے، اور تمہاری چالیں بڑی سخت ہیں۔ یوسف! اس بات کو جانے دو؛ اور تم (عورت) اپنے گناہ کی معافی مانگو۔"],
 ["v","12:25-29","Aur dono darwaze ki taraf daude, aur us (aurat) ne unki qameez peeche se phaad di, aur dono ne uske shauhar ko darwaze ke paas paaya… (Ghar walon mein se ek gawah ne gawahi di:) agar uski qameez aage se phati hai to aurat sacchi hai aur woh jhoote hain; aur agar qameez peeche se phati hai to aurat jhooti hai aur woh sacche hain. Phir jab (shauhar ne) dekha ki qameez peeche se phati hai to kaha: yeh tum auraton ki chaal hai; beshak tumhari chaal badi sakht hai. Yusuf! is se dar-guzar karo; aur (ae aurat) tu apne gunah ki maafi maang, beshak tu hi khatakaar thi.","اور دونوں دروازے کی طرف دوڑے، اور اس (عورت) نے ان کی قمیص پیچھے سے پھاڑ دی، اور دونوں نے اس کے شوہر کو دروازے کے پاس پایا… (گھر والوں میں سے ایک گواہ نے گواہی دی:) اگر اس کی قمیص آگے سے پھٹی ہے تو عورت سچی ہے اور وہ جھوٹے ہیں؛ اور اگر قمیص پیچھے سے پھٹی ہے تو عورت جھوٹی ہے اور وہ سچے ہیں۔ پھر جب (شوہر نے) دیکھا کہ قمیص پیچھے سے پھٹی ہے تو کہا: یہ تم عورتوں کی چال ہے؛ بے شک تمہاری چال بڑی سخت ہے۔ یوسف! اس سے درگزر کرو؛ اور (اے عورت) تو اپنے گناہ کی معافی مانگ، بے شک تو ہی خطاکار تھی۔"],
 ["n","Gawah kaun tha, Quran ne nahi bataya. 'Jhoole mein bachche ke bolne' wali riwayat sahih sanad se saabit nahi.","گواہ کون تھا، قرآن نے نہیں بتایا۔ 'جھولے میں بچے کے بولنے' والی روایت صحیح سند سے ثابت نہیں۔"],

 ["h","Shehar ki auratein aur kati hui ungliyan","شہر کی عورتیں اور کٹی ہوئی انگلیاں"],
 ["p","Baat shehar mein phail gayi. Auratein taane dene lagin: Azeez ki biwi apne ghulam par fareefta hai! Usne un sab ko dawat par bulaya, har ek ke haath mein chhuri aur phal diya, aur Yusuf (AS) se kaha: inke saamne aao. Jab auraton ne unhein dekha to hairaan reh gayin, apne haath kaat liye aur kehne lagin: Haasha lillah! yeh insaan nahi, yeh to koi buzurg farishta hai! Tab usne kaha: yahi hai woh jiske baare mein tum mujhe malaamat karti thin. Main ne ise phuslaya tha magar yeh bach gaya; aur agar ab bhi isne mera kehna na maana to zaroor qaid kiya jaayega aur zaleel hoga.","بات شہر میں پھیل گئی۔ عورتیں طعنے دینے لگیں: عزیز کی بیوی اپنے غلام پر فریفتہ ہے! اس نے ان سب کو دعوت پر بلایا، ہر ایک کے ہاتھ میں چھری اور پھل دیا، اور یوسف علیہ السلام سے کہا: ان کے سامنے آؤ۔ جب عورتوں نے انہیں دیکھا تو حیران رہ گئیں، اپنے ہاتھ کاٹ لیے اور کہنے لگیں: حاشا للہ! یہ انسان نہیں، یہ تو کوئی بزرگ فرشتہ ہے! تب اس نے کہا: یہی ہے وہ جس کے بارے میں تم مجھے ملامت کرتی تھیں۔ میں نے اسے پھسلایا تھا مگر یہ بچ گیا؛ اور اگر اب بھی اس نے میرا کہنا نہ مانا تو ضرور قید کیا جائے گا اور ذلیل ہوگا۔"],
 ["v","12:31-32","… Phir jab unhone unhein dekha to unhein bahut bada paaya aur apne haath kaat liye, aur kaha: Haasha lillah! yeh aadmi nahi, yeh to koi buzurg farishta hai. (Aurat ne) kaha: yahi hai woh jiske baare mein tum mujhe malaamat karti thin. Aur beshak main ne ise phuslaya tha, magar yeh bacha raha; aur agar isne woh na kiya jo main ise hukm deti hoon to zaroor qaid kiya jaayega aur zaroor zaleel hoga.","… پھر جب انہوں نے انہیں دیکھا تو انہیں بہت بڑا پایا اور اپنے ہاتھ کاٹ لیے، اور کہا: حاشا للہ! یہ آدمی نہیں، یہ تو کوئی بزرگ فرشتہ ہے۔ (عورت نے) کہا: یہی ہے وہ جس کے بارے میں تم مجھے ملامت کرتی تھیں۔ اور بے شک میں نے اسے پھسلایا تھا، مگر یہ بچا رہا؛ اور اگر اس نے وہ نہ کیا جو میں اسے حکم دیتی ہوں تو ضرور قید کیا جائے گا اور ضرور ذلیل ہوگا۔"],
 ["h","Qaid gunah se behtar","قید گناہ سے بہتر"],
 ["p","Ab fitna ek aurat ka nahi, poore shehar ki auraton ka tha. Yusuf (AS) ne Allah se dua ki: ae mere Rab! jis cheez ki taraf yeh mujhe bulaati hain us se mujhe qaid zyada pasand hai. Aur agar tu ne inki chaal mujh se na pheri to main inki taraf maail ho jaaunga aur jaahilon mein se ho jaaunga. Dekhiye — itne paakbaaz hokar bhi apni taqat par bharosa nahi, balki Allah se madad maangi. Allah ne dua qubool ki. Phir saaf saboot ke bawajood, ghar ki badnaami chhupaane ke liye Yusuf (AS) ko qaid kar diya gaya.","اب فتنہ ایک عورت کا نہیں، پورے شہر کی عورتوں کا تھا۔ یوسف علیہ السلام نے اللہ سے دعا کی: اے میرے رب! جس چیز کی طرف یہ مجھے بلاتی ہیں اس سے مجھے قید زیادہ پسند ہے۔ اور اگر تو نے ان کی چال مجھ سے نہ پھیری تو میں ان کی طرف مائل ہو جاؤں گا اور جاہلوں میں سے ہو جاؤں گا۔ دیکھیے — اتنے پاکباز ہو کر بھی اپنی طاقت پر بھروسہ نہیں، بلکہ اللہ سے مدد مانگی۔ اللہ نے دعا قبول کی۔ پھر صاف ثبوت کے باوجود، گھر کی بدنامی چھپانے کے لیے یوسف علیہ السلام کو قید کر دیا گیا۔"],
 ["v","12:33-35","(Yusuf ne) kaha: ae mere Rab! jis cheez ki taraf yeh mujhe bulaati hain us se mujhe qaid zyada pasand hai; aur agar tu ne inki chaal mujh se na pheri to main inki taraf jhuk jaaunga aur nadaanon mein se ho jaaunga. To unke Rab ne unki dua qubool ki aur un se unki chaal pher di; beshak woh sunne wala, jaanne wala hai. Phir nishaaniyan dekh lene ke baad bhi unhein yahi munasib laga ki ek muddat ke liye unhein qaid kar dein.","(یوسف نے) کہا: اے میرے رب! جس چیز کی طرف یہ مجھے بلاتی ہیں اس سے مجھے قید زیادہ پسند ہے؛ اور اگر تو نے ان کی چال مجھ سے نہ پھیری تو میں ان کی طرف جھک جاؤں گا اور نادانوں میں سے ہو جاؤں گا۔ تو ان کے رب نے ان کی دعا قبول کی اور ان سے ان کی چال پھیر دی؛ بے شک وہ سننے والا، جاننے والا ہے۔ پھر نشانیاں دیکھ لینے کے بعد بھی انہیں یہی مناسب لگا کہ ایک مدت کے لیے انہیں قید کر دیں۔"],

 ["h","Qaid khaane mein dawat","قید خانے میں دعوت"],
 ["p","Qaid mein Yusuf (AS) ke saath do naujawan aur daakhil hue — ek badshah ka saaqi (pilane wala), doosra naanbaai. Dono ne khwab dekhe. Ek ne kaha: main ne dekha ki sharaab ke liye angoor nichod raha hoon. Doosre ne kaha: main ne dekha ki sar par rotiyan utha rakhi hain aur parinde unhein kha rahe hain. Dono ne kaha: aap hamein ta'beer bataiye, hum aapko nekokar dekhte hain.","قید میں یوسف علیہ السلام کے ساتھ دو نوجوان اور داخل ہوئے — ایک بادشاہ کا ساقی (پلانے والا)، دوسرا نانبائی۔ دونوں نے خواب دیکھے۔ ایک نے کہا: میں نے دیکھا کہ شراب کے لیے انگور نچوڑ رہا ہوں۔ دوسرے نے کہا: میں نے دیکھا کہ سر پر روٹیاں اٹھا رکھی ہیں اور پرندے انہیں کھا رہے ہیں۔ دونوں نے کہا: آپ ہمیں تعبیر بتائیے، ہم آپ کو نیکوکار دیکھتے ہیں۔"],
 ["p","Yahan Yusuf (AS) ki hikmat dekhiye: ta'beer foran nahi batayi. Pehle unhein itminaan dilaya ki khaana aane se pehle ta'beer bata dunga, phir mauqa dekh kar tauheed ki dawat di. Logon ko jab tumhari zaroorat ho, wahi dawat ka sab se achha waqt hai.","یہاں یوسف علیہ السلام کی حکمت دیکھیے: تعبیر فوراً نہیں بتائی۔ پہلے انہیں اطمینان دلایا کہ کھانا آنے سے پہلے تعبیر بتا دوں گا، پھر موقع دیکھ کر توحید کی دعوت دی۔ لوگوں کو جب تمہاری ضرورت ہو، وہی دعوت کا سب سے اچھا وقت ہے۔"],
 ["v","12:39-40","Ae qaid ke mere dono saathiyo! kya alag alag kai rab behtar hain ya akela Allah jo sab par ghaalib hai? Tum uske siwa jinki ibadat karte ho woh bas naam hain jo tumne aur tumhare baap dada ne rakh liye hain, Allah ne unki koi sanad nahi utaari. Hukm sirf Allah ka hai; usne hukm diya hai ki uske siwa kisi ki ibadat na karo. Yahi seedha deen hai, lekin aksar log nahi jaante.","اے قید کے میرے دونوں ساتھیو! کیا الگ الگ کئی رب بہتر ہیں یا اکیلا اللہ جو سب پر غالب ہے؟ تم اس کے سوا جن کی عبادت کرتے ہو وہ بس نام ہیں جو تم نے اور تمہارے باپ دادا نے رکھ لیے ہیں، اللہ نے ان کی کوئی سند نہیں اتاری۔ حکم صرف اللہ کا ہے؛ اس نے حکم دیا ہے کہ اس کے سوا کسی کی عبادت نہ کرو۔ یہی سیدھا دین ہے، لیکن اکثر لوگ نہیں جانتے۔"],
 ["p","Phir ta'beer batayi: tum mein se ek apne maalik (badshah) ko phir sharaab pilayega; aur doosra sooli diya jaayega aur parinde uska sar khaayenge. Jo bachne wala tha usse kaha: apne maalik ke paas mera zikr karna (ki ek begunah qaid mein hai). Lekin shaitan ne use bhula diya, aur Yusuf (AS) kai saal qaid mein rahe.","پھر تعبیر بتائی: تم میں سے ایک اپنے مالک (بادشاہ) کو پھر شراب پلائے گا؛ اور دوسرا سولی دیا جائے گا اور پرندے اس کا سر کھائیں گے۔ جو بچنے والا تھا اس سے کہا: اپنے مالک کے پاس میرا ذکر کرنا (کہ ایک بے گناہ قید میں ہے)۔ لیکن شیطان نے اسے بھلا دیا، اور یوسف علیہ السلام کئی سال قید میں رہے۔"],
 ["v","12:41-42","Ae qaid ke mere dono saathiyo! tum mein se ek to apne maalik ko sharaab pilayega; aur doosra sooli par chadhaaya jaayega to parinde uske sar mein se khaayenge. Jis baat ke baare mein tum poochte the uska faisla ho chuka. Aur jis ke baare mein unhone samjha ki woh bach jaayega us se kaha: apne maalik ke paas mera zikr karna. Magar shaitan ne use apne maalik se zikr karna bhula diya, to woh kai saal qaid mein rahe.","اے قید کے میرے دونوں ساتھیو! تم میں سے ایک تو اپنے مالک کو شراب پلائے گا؛ اور دوسرا سولی پر چڑھایا جائے گا تو پرندے اس کے سر میں سے کھائیں گے۔ جس بات کے بارے میں تم پوچھتے تھے اس کا فیصلہ ہو چکا۔ اور جس کے بارے میں انہوں نے سمجھا کہ وہ بچ جائے گا اس سے کہا: اپنے مالک کے پاس میرا ذکر کرنا۔ مگر شیطان نے اسے اپنے مالک سے ذکر کرنا بھلا دیا، تو وہ کئی سال قید میں رہے۔"],

 ["h","Badshah ka khwab","بادشاہ کا خواب"],
 ["p","Phir ek din badshah ne khwab dekha: saat moti gaayein hain jinhein saat dubli gaayein kha rahi hain, aur saat hari baaliyan hain aur saat sookhi. Darbar ke sab ulama aur jaadugar hairaan reh gaye: yeh to pareshaan khwab hain, hum inki ta'beer nahi jaante. Tab saaqi ko — saalon baad — Yusuf (AS) yaad aaye. Woh qaid khaane gaya.","پھر ایک دن بادشاہ نے خواب دیکھا: سات موٹی گائیں ہیں جنہیں سات دبلی گائیں کھا رہی ہیں، اور سات ہری بالیاں ہیں اور سات سوکھی۔ دربار کے سب علماء اور جادوگر حیران رہ گئے: یہ تو پریشان خواب ہیں، ہم ان کی تعبیر نہیں جانتے۔ تب ساقی کو — سالوں بعد — یوسف علیہ السلام یاد آئے۔ وہ قید خانے گیا۔"],
 ["p","Ab Yusuf (AS) ka bada pan dekhiye: na shikayat ki ki 'tum ne mujhe saalon bhula diya', na koi shart rakhi ki 'pehle mujhe chhudwao'. Foran ta'beer bhi batayi aur uska hal bhi: saat saal khoob kheti karo, aur jo kaato use baaliyon hi mein rehne do, sirf khaane bhar nikalo. Phir saat sakht saal aayenge jo pichhla jama kiya hua kha jaayenge. Phir ek saal aayega jismein logon par khoob baarish hogi.","اب یوسف علیہ السلام کا بڑا پن دیکھیے: نہ شکایت کی کہ 'تم نے مجھے سالوں بھلا دیا'، نہ کوئی شرط رکھی کہ 'پہلے مجھے چھڑواؤ'۔ فوراً تعبیر بھی بتائی اور اس کا حل بھی: سات سال خوب کھیتی کرو، اور جو کاٹو اسے بالیوں ہی میں رہنے دو، صرف کھانے بھر نکالو۔ پھر سات سخت سال آئیں گے جو پچھلا جمع کیا ہوا کھا جائیں گے۔ پھر ایک سال آئے گا جس میں لوگوں پر خوب بارش ہوگی۔"],
 ["v","12:46-49","Yusuf! ae sacche! hamein saat moti gaayon ke baare mein bataiye jinhein saat dubli kha rahi hain, aur saat hari baaliyon aur (saat) sookhi ke baare mein, taaki main logon ke paas laut kar jaaun, shayad woh jaan lein. (Yusuf ne) kaha: tum saat saal lagaataar kheti karoge, to jo kaato use uski baali hi mein rehne do, siwaye thode se jo tum khaao. Phir uske baad saat sakht saal aayenge jo woh sab kha jaayenge jo tumne unke liye pehle se rakha hoga, siwaye thode se jo tum bacha loge. Phir uske baad ek saal aayega jismein logon par baarish barsaayi jaayegi aur us mein woh ras nichodenge.","یوسف! اے سچے! ہمیں سات موٹی گایوں کے بارے میں بتائیے جنہیں سات دبلی کھا رہی ہیں، اور سات ہری بالیوں اور (سات) سوکھی کے بارے میں، تاکہ میں لوگوں کے پاس لوٹ کر جاؤں، شاید وہ جان لیں۔ (یوسف نے) کہا: تم سات سال لگاتار کھیتی کرو گے، تو جو کاٹو اسے اس کی بالی ہی میں رہنے دو، سوائے تھوڑے سے جو تم کھاؤ۔ پھر اس کے بعد سات سخت سال آئیں گے جو وہ سب کھا جائیں گے جو تم نے ان کے لیے پہلے سے رکھا ہوگا، سوائے تھوڑے سے جو تم بچا لو گے۔ پھر اس کے بعد ایک سال آئے گا جس میں لوگوں پر بارش برسائی جائے گی اور اس میں وہ رس نچوڑیں گے۔"],

 ["h","Pehle begunahi, phir rihaai","پہلے بے گناہی، پھر رہائی"],
 ["p","Badshah ne kaha: use mere paas lao! Qaasid aaya — aur Yusuf (AS) ne baahar aane se inkaar kar diya! Farmaya: apne maalik ke paas wapas jaao aur us se poochho ki un auraton ka kya maamla tha jinhone apne haath kaate the. Yaani pehle meri begunahi saabit ho, phir baahar aaunga — taaki koi kal yeh na kahe ki ek mujrim ko chhod diya gaya. Badshah ne auraton ko bulaya. Sab ne kaha: Haasha lillah! hum ne us mein koi buraai nahi dekhi. Aur Azeez ki biwi ne bhi khud iqraar kiya: ab haq saaf ho gaya, main ne hi use phuslaya tha, aur woh bilkul saccha hai.","بادشاہ نے کہا: اسے میرے پاس لاؤ! قاصد آیا — اور یوسف علیہ السلام نے باہر آنے سے انکار کر دیا! فرمایا: اپنے مالک کے پاس واپس جاؤ اور اس سے پوچھو کہ ان عورتوں کا کیا معاملہ تھا جنہوں نے اپنے ہاتھ کاٹے تھے۔ یعنی پہلے میری بے گناہی ثابت ہو، پھر باہر آؤں گا — تاکہ کوئی کل یہ نہ کہے کہ ایک مجرم کو چھوڑ دیا گیا۔ بادشاہ نے عورتوں کو بلایا۔ سب نے کہا: حاشا للہ! ہم نے اس میں کوئی برائی نہیں دیکھی۔ اور عزیز کی بیوی نے بھی خود اقرار کیا: اب حق صاف ہو گیا، میں نے ہی اسے پھسلایا تھا، اور وہ بالکل سچا ہے۔"],
 ["v","12:50-51","Aur badshah ne kaha: use mere paas lao. Phir jab qaasid unke paas aaya to (Yusuf ne) kaha: apne maalik ke paas laut jaao aur us se poochho ki un auraton ka kya haal hai jinhone apne haath kaat liye the; beshak mera Rab unki chaal ko khoob jaanta hai. (Badshah ne auraton se) kaha: tumhara kya maamla tha jab tumne Yusuf ko phuslaya? Unhone kaha: Haasha lillah! hum ne us mein koi buraai nahi jaani. Azeez ki biwi ne kaha: ab haq zaahir ho gaya; main ne hi use phuslaya tha, aur beshak woh sacchon mein se hai.","اور بادشاہ نے کہا: اسے میرے پاس لاؤ۔ پھر جب قاصد ان کے پاس آیا تو (یوسف نے) کہا: اپنے مالک کے پاس لوٹ جاؤ اور اس سے پوچھو کہ ان عورتوں کا کیا حال ہے جنہوں نے اپنے ہاتھ کاٹ لیے تھے؛ بے شک میرا رب ان کی چال کو خوب جانتا ہے۔ (بادشاہ نے عورتوں سے) کہا: تمہارا کیا معاملہ تھا جب تم نے یوسف کو پھسلایا؟ انہوں نے کہا: حاشا للہ! ہم نے اس میں کوئی برائی نہیں جانی۔ عزیز کی بیوی نے کہا: اب حق ظاہر ہو گیا؛ میں نے ہی اسے پھسلایا تھا، اور بے شک وہ سچوں میں سے ہے۔"],
 ["p","Nabi ﷺ ne Yusuf (AS) ke is sabr ki tareef mein farmaya: agar main qaid mein itni muddat rehta jitna Yusuf rahe, to bulaane wale ki baat foran maan leta.","نبی ﷺ نے یوسف علیہ السلام کے اس صبر کی تعریف میں فرمایا: اگر میں قید میں اتنی مدت رہتا جتنا یوسف رہے، تو بلانے والے کی بات فوراً مان لیتا۔"],
 ["n","Sahih Bukhari aur Sahih Muslim. Yeh Nabi ﷺ ki tawazo' aur Yusuf (AS) ke sabr ki tareef hai.","صحیح بخاری اور صحیح مسلم۔ یہ نبی ﷺ کی تواضع اور یوسف علیہ السلام کے صبر کی تعریف ہے۔"],
 ["v","12:53","Aur main apne nafs ko bari (paak) nahi kehta; beshak nafs to buraai hi ka hukm deta hai, siwaye uske jis par mera Rab reham kare; beshak mera Rab bakhshne wala, meharbaan hai.","اور میں اپنے نفس کو بری (پاک) نہیں کہتا؛ بے شک نفس تو برائی ہی کا حکم دیتا ہے، سوائے اس کے جس پر میرا رب رحم کرے؛ بے شک میرا رب بخشنے والا، مہربان ہے۔"],

 ["n","Qissa jaari hai — agla chapter: Hissa 2.","قصہ جاری ہے — اگلا چیپٹر: حصہ ٢۔"]
]},
{ro:"Hazrat Yusuf (AS) — Hissa 2: Izzat, milaap aur maafi", ur:"حضرت یوسف علیہ السلام — حصہ ٢: عزت، ملاپ اور معافی", b:[
 ["p","Pichhle hisse mein humne dekha ki Yusuf (AS) ko bhaiyon ne kuein mein daala, Misr mein beche gaye, Azeez ki biwi ke fitne mein paakdaaman rahe, begunah qaid hue, qaid mein dawat di, badshah ke khwab ki ta'beer batayi, aur rihaai se pehle apni begunahi saabit karwaai. Ab qissa wahan se aage badhta hai jahan Allah unhein qaid se utha kar Misr ke khazaanon ka maalik banata hai.","پچھلے حصے میں ہم نے دیکھا کہ یوسف علیہ السلام کو بھائیوں نے کنویں میں ڈالا، مصر میں بیچے گئے، عزیز کی بیوی کے فتنے میں پاکدامن رہے، بے گناہ قید ہوئے، قید میں دعوت دی، بادشاہ کے خواب کی تعبیر بتائی، اور رہائی سے پہلے اپنی بے گناہی ثابت کروائی۔ اب قصہ وہاں سے آگے بڑھتا ہے جہاں اللہ انہیں قید سے اٹھا کر مصر کے خزانوں کا مالک بناتا ہے۔"],
 ["h","Qaid se khazaanon tak","قید سے خزانوں تک"],
 ["p","Badshah ne kaha: use mere paas lao, main use apne khaas kaam ke liye rakhoonga. Baat cheet ke baad kaha: aaj se tum hamare yahan mo'tabar aur ameen ho. Yusuf (AS) ne kaha: mujhe mulk ke khazaanon par muqarrar kar dijiye, main hifazat karne wala aur jaanne wala hoon. Yeh ohda maangna lalach nahi tha — woh jaante the ki aane wale qahat mein qaum ko sirf woh bacha sakte hain. Kal ka ghulam, kal ka qaidi, aaj Misr ka wazeer-e-khazaana tha.","بادشاہ نے کہا: اسے میرے پاس لاؤ، میں اسے اپنے خاص کام کے لیے رکھوں گا۔ بات چیت کے بعد کہا: آج سے تم ہمارے یہاں معتبر اور امین ہو۔ یوسف علیہ السلام نے کہا: مجھے ملک کے خزانوں پر مقرر کر دیجیے، میں حفاظت کرنے والا اور جاننے والا ہوں۔ یہ عہدہ مانگنا لالچ نہیں تھا — وہ جانتے تھے کہ آنے والے قحط میں قوم کو صرف وہ بچا سکتے ہیں۔ کل کا غلام، کل کا قیدی، آج مصر کا وزیرِ خزانہ تھا۔"],
 ["v","12:54-56","Aur badshah ne kaha: use mere paas lao, main use apne liye khaas kar loonga. Phir jab us se baat ki to kaha: aaj se tum hamare yahan mo'tabar aur ameen ho. (Yusuf ne) kaha: mujhe mulk ke khazaanon par muqarrar kar dijiye; main hifazat karne wala, jaanne wala hoon. Aur isi tarah humne Yusuf ko us mulk mein ikhtiyaar diya ki us mein jahan chahein rahein. Hum apni rehmat jise chahte hain pahunchaate hain, aur nekokaron ka ajr zaaya nahi karte.","اور بادشاہ نے کہا: اسے میرے پاس لاؤ، میں اسے اپنے لیے خاص کر لوں گا۔ پھر جب اس سے بات کی تو کہا: آج سے تم ہمارے یہاں معتبر اور امین ہو۔ (یوسف نے) کہا: مجھے ملک کے خزانوں پر مقرر کر دیجیے؛ میں حفاظت کرنے والا، جاننے والا ہوں۔ اور اسی طرح ہم نے یوسف کو اس ملک میں اختیار دیا کہ اس میں جہاں چاہیں رہیں۔ ہم اپنی رحمت جسے چاہتے ہیں پہنچاتے ہیں، اور نیکوکاروں کا اجر ضائع نہیں کرتے۔"],

 ["h","Bhai ghalla lene aaye","بھائی غلہ لینے آئے"],
 ["p","Saat khushhaali ke saal guzre, phir qahat shuru hua — sirf Misr nahi, aas paas ke mulkon mein bhi, Kan'aan (Palestine) tak. Wahan se Yaqub (AS) ke das bete ghalla lene Misr aaye aur Yusuf (AS) ke saamne pesh hue. Yusuf (AS) ne unhein pehchaan liya, lekin woh unhein na pehchaan sake — jis bachche ko kuein mein phenka tha, woh aaj Misr ka hakim kaise ho sakta tha? Yusuf (AS) ne unhein ghalla diya aur kaha: agli baar apne us bhai ko bhi lana jo tumhare baap ki taraf se hai (Bin-Yameen); agar na laaye to tumhein yahan se ghalla nahi milega. Aur chupke se unki raqam bhi unke saamaan mein wapas rakhwa di.","سات خوشحالی کے سال گزرے، پھر قحط شروع ہوا — صرف مصر نہیں، آس پاس کے ملکوں میں بھی، کنعان (فلسطین) تک۔ وہاں سے یعقوب علیہ السلام کے دس بیٹے غلہ لینے مصر آئے اور یوسف علیہ السلام کے سامنے پیش ہوئے۔ یوسف علیہ السلام نے انہیں پہچان لیا، لیکن وہ انہیں نہ پہچان سکے — جس بچے کو کنویں میں پھینکا تھا، وہ آج مصر کا حاکم کیسے ہو سکتا تھا؟ یوسف علیہ السلام نے انہیں غلہ دیا اور کہا: اگلی بار اپنے اس بھائی کو بھی لانا جو تمہارے باپ کی طرف سے ہے (بن یامین)؛ اگر نہ لائے تو تمہیں یہاں سے غلہ نہیں ملے گا۔ اور چپکے سے ان کی رقم بھی ان کے سامان میں واپس رکھوا دی۔"],
 ["v","12:58-60","Aur Yusuf ke bhai aaye aur unke paas pahunche, to unhone unhein pehchaan liya aur woh unhein na pehchaan sake. Aur jab unka saamaan taiyaar kar diya to kaha: apne us bhai ko mere paas lana jo tumhare baap ki taraf se hai; kya tum nahi dekhte ki main poora naap deta hoon aur main behtareen mehmaan-nawaaz hoon? Phir agar tum use mere paas na laaye to mere paas tumhare liye koi naap nahi, aur mere qareeb bhi na aana.","اور یوسف کے بھائی آئے اور ان کے پاس پہنچے، تو انہوں نے انہیں پہچان لیا اور وہ انہیں نہ پہچان سکے۔ اور جب ان کا سامان تیار کر دیا تو کہا: اپنے اس بھائی کو میرے پاس لانا جو تمہارے باپ کی طرف سے ہے؛ کیا تم نہیں دیکھتے کہ میں پورا ناپ دیتا ہوں اور میں بہترین مہمان نواز ہوں؟ پھر اگر تم اسے میرے پاس نہ لائے تو میرے پاس تمہارے لیے کوئی ناپ نہیں، اور میرے قریب بھی نہ آنا۔"],
 ["h","Yaqub (AS) ka doosra imtihaan","یعقوب علیہ السلام کا دوسرا امتحان"],
 ["p","Bete wapas aaye aur baap se kaha: Bin-Yameen ko hamare saath bhejiye warna ghalla nahi milega; hum uski hifazat karenge. Yaqub (AS) ka dil ek baar zakhmi ho chuka tha: kya main is par bhi tum par waisa hi bharosa karoon jaisa is se pehle uske bhai par kiya tha? Phir jab unhone saamaan khola to dekha ki raqam wapas aa gayi hai. Aakhir Yaqub (AS) ne un se Allah ka pakka ahad liya ki use zaroor wapas laaoge, siwaye iske ki tum sab ghir jaao. Aur farmaya: Allah behtareen hifazat karne wala hai.","بیٹے واپس آئے اور باپ سے کہا: بن یامین کو ہمارے ساتھ بھیجیے ورنہ غلہ نہیں ملے گا؛ ہم اس کی حفاظت کریں گے۔ یعقوب علیہ السلام کا دل ایک بار زخمی ہو چکا تھا: کیا میں اس پر بھی تم پر ویسا ہی بھروسہ کروں جیسا اس سے پہلے اس کے بھائی پر کیا تھا؟ پھر جب انہوں نے سامان کھولا تو دیکھا کہ رقم واپس آ گئی ہے۔ آخر یعقوب علیہ السلام نے ان سے اللہ کا پکا عہد لیا کہ اسے ضرور واپس لاؤ گے، سوائے اس کے کہ تم سب گھر جاؤ۔ اور فرمایا: اللہ بہترین حفاظت کرنے والا ہے۔"],
 ["v","12:64","(Yaqub ne) kaha: kya main is ke baare mein tum par waisa hi bharosa karoon jaisa is se pehle iske bhai ke baare mein kar chuka hoon? To Allah hi behtareen nigehbaan hai, aur woh sab meharbaanon se badh kar meharbaan hai.","(یعقوب نے) کہا: کیا میں اس کے بارے میں تم پر ویسا ہی بھروسہ کروں جیسا اس سے پہلے اس کے بھائی کے بارے میں کر چکا ہوں؟ تو اللہ ہی بہترین نگہبان ہے، اور وہ سب مہربانوں سے بڑھ کر مہربان ہے۔"],
 ["p","Yaqub (AS) ne tadbeer bhi batayi: shehar mein ek hi darwaze se daakhil na hona, alag alag darwazon se jaana. Phir farmaya: main Allah ke faisle ko tum se taal nahi sakta; hukm sirf Allah ka hai, maine usi par bharosa kiya. Yeh tawakkul aur asbaab ka sahih tawazun hai: tadbeer bhi karo, bharosa Allah par rakho.","یعقوب علیہ السلام نے تدبیر بھی بتائی: شہر میں ایک ہی دروازے سے داخل نہ ہونا، الگ الگ دروازوں سے جانا۔ پھر فرمایا: میں اللہ کے فیصلے کو تم سے ٹال نہیں سکتا؛ حکم صرف اللہ کا ہے، میں نے اسی پر بھروسہ کیا۔ یہ توکل اور اسباب کا صحیح توازن ہے: تدبیر بھی کرو، بھروسہ اللہ پر رکھو۔"],
 ["v","12:67","Aur kaha: ae mere beto! ek darwaze se daakhil na hona, balki alag alag darwazon se daakhil hona; aur main Allah (ke faisle) se tumhein kuch nahi bacha sakta. Hukm sirf Allah ka hai; maine usi par bharosa kiya, aur bharosa karne walon ko usi par bharosa karna chahiye.","اور کہا: اے میرے بیٹو! ایک دروازے سے داخل نہ ہونا، بلکہ الگ الگ دروازوں سے داخل ہونا؛ اور میں اللہ (کے فیصلے) سے تمہیں کچھ نہیں بچا سکتا۔ حکم صرف اللہ کا ہے؛ میں نے اسی پر بھروسہ کیا، اور بھروسہ کرنے والوں کو اسی پر بھروسہ کرنا چاہیے۔"],

 ["h","Shahi pyaala aur Bin-Yameen","شاہی پیالہ اور بن یامین"],
 ["p","Jab bhai Bin-Yameen ko lekar aaye, to Yusuf (AS) ne apne sage bhai ko alag bulaya aur bata diya: main tumhara bhai (Yusuf) hoon, to jo yeh karte rahe us par ghamgeen na ho. Phir Allah ki tadbeer se Yusuf (AS) ne Bin-Yameen ko apne paas rokne ka intezaam kiya: shahi naapne ka pyaala Bin-Yameen ke saamaan mein rakhwa diya. Qaafila chala to munaadi hui: ae qaafile walo! tum chor ho! Bhai hairaan: hum yahan fasaad karne nahi aaye, aur hum chor nahi. Poocha gaya: agar tum jhoote nikle to chor ki saza kya hai? Unhone apni shariat ke mutabiq kaha: jiske saamaan se nikle wahi rok liya jaaye. Talaashi hui aur pyaala Bin-Yameen ke saamaan se nikla.","جب بھائی بن یامین کو لے کر آئے، تو یوسف علیہ السلام نے اپنے سگے بھائی کو الگ بلایا اور بتا دیا: میں تمہارا بھائی (یوسف) ہوں، تو جو یہ کرتے رہے اس پر غمگین نہ ہو۔ پھر اللہ کی تدبیر سے یوسف علیہ السلام نے بن یامین کو اپنے پاس روکنے کا انتظام کیا: شاہی ناپنے کا پیالہ بن یامین کے سامان میں رکھوا دیا۔ قافلہ چلا تو منادی ہوئی: اے قافلے والو! تم چور ہو! بھائی حیران: ہم یہاں فساد کرنے نہیں آئے، اور ہم چور نہیں۔ پوچھا گیا: اگر تم جھوٹے نکلے تو چور کی سزا کیا ہے؟ انہوں نے اپنی شریعت کے مطابق کہا: جس کے سامان سے نکلے وہی روک لیا جائے۔ تلاشی ہوئی اور پیالہ بن یامین کے سامان سے نکلا۔"],
 ["v","12:69","Aur jab woh Yusuf ke paas pahunche to unhone apne bhai ko apne paas jagah di (aur) kaha: main tumhara bhai hoon, to jo kuch yeh karte rahe hain us par ranjeeda na ho.","اور جب وہ یوسف کے پاس پہنچے تو انہوں نے اپنے بھائی کو اپنے پاس جگہ دی (اور) کہا: میں تمہارا بھائی ہوں، تو جو کچھ یہ کرتے رہے ہیں اس پر رنجیدہ نہ ہو۔"],
 ["v","12:76","… Isi tarah humne Yusuf ke liye tadbeer ki; woh badshah ke qanoon ke mutabiq apne bhai ko nahi le sakte the magar yeh ki Allah chahe. Hum jiske chahte hain darje buland karte hain; aur har ilm wale se upar ek ilm wala hai.","… اسی طرح ہم نے یوسف کے لیے تدبیر کی؛ وہ بادشاہ کے قانون کے مطابق اپنے بھائی کو نہیں لے سکتے تھے مگر یہ کہ اللہ چاہے۔ ہم جس کے چاہتے ہیں درجے بلند کرتے ہیں؛ اور ہر علم والے سے اوپر ایک علم والا ہے۔"],
 ["p","Bhaiyon ne phir wahi purana hasad dikhaya: agar isne chori ki hai to iske bhai (Yusuf) ne bhi pehle chori ki thi! Yusuf (AS) ne yeh ilzaam sun kar bhi apne aap ko zaahir na kiya, dil mein hi rakha. Bhaiyon ne kaha: iska baap bahut boodha hai, iski jagah hum mein se kisi ko rakh lijiye. Farmaya: Allah ki panaah ki hum uske siwa kisi ko pakdein jiske paas hamara saamaan mila.","بھائیوں نے پھر وہی پرانا حسد دکھایا: اگر اس نے چوری کی ہے تو اس کے بھائی (یوسف) نے بھی پہلے چوری کی تھی! یوسف علیہ السلام نے یہ الزام سن کر بھی اپنے آپ کو ظاہر نہ کیا، دل میں ہی رکھا۔ بھائیوں نے کہا: اس کا باپ بہت بوڑھا ہے، اس کی جگہ ہم میں سے کسی کو رکھ لیجیے۔ فرمایا: اللہ کی پناہ کہ ہم اس کے سوا کسی کو پکڑیں جس کے پاس ہمارا سامان ملا۔"],
 ["h","Bada bhai ruk gaya","بڑا بھائی رک گیا"],
 ["p","Ab bhai sakht pareshaan the. Sab se bade bhai ne kaha: tum jaante ho tumhare baap ne tum se Allah ka ahad liya tha, aur is se pehle Yusuf ke maamle mein tum kotaahi kar chuke ho. Main to yahan se nahi hilunga jab tak abba mujhe ijazat na dein ya Allah mere liye koi faisla na kare. Tum jaao aur abba se kaho ki aapke bete ne chori ki.","اب بھائی سخت پریشان تھے۔ سب سے بڑے بھائی نے کہا: تم جانتے ہو تمہارے باپ نے تم سے اللہ کا عہد لیا تھا، اور اس سے پہلے یوسف کے معاملے میں تم کوتاہی کر چکے ہو۔ میں تو یہاں سے نہیں ہلوں گا جب تک ابا مجھے اجازت نہ دیں یا اللہ میرے لیے کوئی فیصلہ نہ کرے۔ تم جاؤ اور ابا سے کہو کہ آپ کے بیٹے نے چوری کی۔"],

 ["h","Yaqub (AS) ka gham aur ummeed","یعقوب علیہ السلام کا غم اور امید"],
 ["p","Yaqub (AS) ne khabar suni to wahi jumla dohraya: balki tumhare nafs ne ek baat bana li hai; to sabr hi behtar hai. Ummeed hai Allah un sab ko mere paas le aayega. Phir munh pher liya aur kaha: haaye Yusuf! Gham se unki aankhein safed ho gayin (beenaai chali gayi), aur woh gham ko dil mein dabaaye rehte the. Bete kehne lage: Allah ki qasam! aap Yusuf ko yaad karte karte ghul jaayenge ya mar jaayenge. Yaqub (AS) ka jawab har ghamzada ke liye raah hai: main apni pareshaani aur gham ki shikayat sirf Allah se karta hoon, aur Allah ki taraf se woh jaanta hoon jo tum nahi jaante.","یعقوب علیہ السلام نے خبر سنی تو وہی جملہ دہرایا: بلکہ تمہارے نفس نے ایک بات بنا لی ہے؛ تو صبر ہی بہتر ہے۔ امید ہے اللہ ان سب کو میرے پاس لے آئے گا۔ پھر منہ پھیر لیا اور کہا: ہائے یوسف! غم سے ان کی آنکھیں سفید ہو گئیں (بینائی چلی گئی)، اور وہ غم کو دل میں دبائے رہتے تھے۔ بیٹے کہنے لگے: اللہ کی قسم! آپ یوسف کو یاد کرتے کرتے گھل جائیں گے یا مر جائیں گے۔ یعقوب علیہ السلام کا جواب ہر غمزدہ کے لیے راہ ہے: میں اپنی پریشانی اور غم کی شکایت صرف اللہ سے کرتا ہوں، اور اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے۔"],
 ["v","12:83-87","(Yaqub ne) kaha: balki tumhare nafs ne tumhare liye ek baat bana li hai; to sabr hi achha hai. Ummeed hai ki Allah un sab ko mere paas le aaye; beshak woh jaanne wala, hikmat wala hai. Aur unse munh pher liya aur kaha: haaye afsos Yusuf par! aur gham se unki aankhein safed ho gayin, aur woh gham ko dabaaye hue the. (Beton ne) kaha: Allah ki qasam! aap Yusuf ko yaad karte rahenge yahan tak ki ghul jaayenge ya halaak ho jaayenge. (Yaqub ne) kaha: main apni pareshaani aur gham ki shikayat sirf Allah se karta hoon, aur main Allah ki taraf se woh jaanta hoon jo tum nahi jaante. Ae mere beto! jaao aur Yusuf aur uske bhai ko talaash karo, aur Allah ki rehmat se na-ummeed na ho; beshak Allah ki rehmat se kaafir log hi na-ummeed hote hain.","(یعقوب نے) کہا: بلکہ تمہارے نفس نے تمہارے لیے ایک بات بنا لی ہے؛ تو صبر ہی اچھا ہے۔ امید ہے کہ اللہ ان سب کو میرے پاس لے آئے؛ بے شک وہ جاننے والا، حکمت والا ہے۔ اور ان سے منہ پھیر لیا اور کہا: ہائے افسوس یوسف پر! اور غم سے ان کی آنکھیں سفید ہو گئیں، اور وہ غم کو دبائے ہوئے تھے۔ (بیٹوں نے) کہا: اللہ کی قسم! آپ یوسف کو یاد کرتے رہیں گے یہاں تک کہ گھل جائیں گے یا ہلاک ہو جائیں گے۔ (یعقوب نے) کہا: میں اپنی پریشانی اور غم کی شکایت صرف اللہ سے کرتا ہوں، اور میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے۔ اے میرے بیٹو! جاؤ اور یوسف اور اس کے بھائی کو تلاش کرو، اور اللہ کی رحمت سے ناامید نہ ہو؛ بے شک اللہ کی رحمت سے کافر لوگ ہی ناامید ہوتے ہیں۔"],
 ["p","Dekhiye: barson baad bhi ummeed zinda thi — 'Yusuf ko talaash karo'. Rona sabr ke khilaf nahi; Nabi ﷺ bhi apne bete Ibrahim ki wafaat par roye the. Sabr ke khilaf yeh hai ki Allah se shikwa ho ya makhlooq ke saamne faryaad ho.","دیکھیے: برسوں بعد بھی امید زندہ تھی — 'یوسف کو تلاش کرو'۔ رونا صبر کے خلاف نہیں؛ نبی ﷺ بھی اپنے بیٹے ابراہیم کی وفات پر روئے تھے۔ صبر کے خلاف یہ ہے کہ اللہ سے شکوہ ہو یا مخلوق کے سامنے فریاد ہو۔"],

 ["h","'Main Yusuf hoon' — maafi ka din","'میں یوسف ہوں' — معافی کا دن"],
 ["p","Bhai teesri baar Misr aaye — is baar toote hue, aajizi ke saath: ae Azeez! hum aur hamare ghar wale musibat mein hain, hum thodi si poonji laaye hain, aap hamein poora ghalla de dijiye aur hum par sadqa kijiye. Ab Yusuf (AS) se raha na gaya. Farmaya: kya tumhein yaad hai tumne Yusuf aur uske bhai ke saath kya kiya tha jab tum nadaan the? Bhai chaunk uthe: kya tum hi Yusuf ho? Farmaya: haan, main Yusuf hoon aur yeh mera bhai hai. Allah ne hum par ehsaan kiya. Jo Allah se darta hai aur sabr karta hai, Allah nekokaron ka ajr zaaya nahi karta.","بھائی تیسری بار مصر آئے — اس بار ٹوٹے ہوئے، عاجزی کے ساتھ: اے عزیز! ہم اور ہمارے گھر والے مصیبت میں ہیں، ہم تھوڑی سی پونجی لائے ہیں، آپ ہمیں پورا غلہ دے دیجیے اور ہم پر صدقہ کیجیے۔ اب یوسف علیہ السلام سے رہا نہ گیا۔ فرمایا: کیا تمہیں یاد ہے تم نے یوسف اور اس کے بھائی کے ساتھ کیا کیا تھا جب تم نادان تھے؟ بھائی چونک اٹھے: کیا تم ہی یوسف ہو؟ فرمایا: ہاں، میں یوسف ہوں اور یہ میرا بھائی ہے۔ اللہ نے ہم پر احسان کیا۔ جو اللہ سے ڈرتا ہے اور صبر کرتا ہے، اللہ نیکوکاروں کا اجر ضائع نہیں کرتا۔"],
 ["v","12:89-92","(Yusuf ne) kaha: kya tum jaante ho ki tumne Yusuf aur uske bhai ke saath kya kiya jab tum nadaan the? Woh bole: kya waqai tum hi Yusuf ho? Kaha: main Yusuf hoon aur yeh mera bhai hai; Allah ne hum par ehsaan kiya. Beshak jo (Allah se) darta hai aur sabr karta hai, to Allah nekokaron ka ajr zaaya nahi karta. Woh bole: Allah ki qasam! Allah ne tumhein hum par fazeelat di, aur beshak hum khatakaar the. (Yusuf ne) kaha: aaj tum par koi malaamat nahi; Allah tumhein maaf kare, aur woh sab meharbaanon se badh kar meharbaan hai.","(یوسف نے) کہا: کیا تم جانتے ہو کہ تم نے یوسف اور اس کے بھائی کے ساتھ کیا کیا جب تم نادان تھے؟ وہ بولے: کیا واقعی تم ہی یوسف ہو؟ کہا: میں یوسف ہوں اور یہ میرا بھائی ہے؛ اللہ نے ہم پر احسان کیا۔ بے شک جو (اللہ سے) ڈرتا ہے اور صبر کرتا ہے، تو اللہ نیکوکاروں کا اجر ضائع نہیں کرتا۔ وہ بولے: اللہ کی قسم! اللہ نے تمہیں ہم پر فضیلت دی، اور بے شک ہم خطاکار تھے۔ (یوسف نے) کہا: آج تم پر کوئی ملامت نہیں؛ اللہ تمہیں معاف کرے، اور وہ سب مہربانوں سے بڑھ کر مہربان ہے۔"],
 ["p","'La tathreeba alaikumul yaum' — aaj tum par koi malaamat nahi! Jinhone kuein mein phenka, ghulam banwaya, saalon baap se juda kiya — aaj woh saamne khade hain, aur Yusuf (AS) ke paas poori taqat hai. Phir bhi na badla, na taana, na sharminda karna. Seerat ki kitabon mein hai ki Fateh-e-Makka ke din Nabi ﷺ ne bhi Quraish se yahi alfaaz farmaaye the.","'لا تثریب علیکم الیوم' — آج تم پر کوئی ملامت نہیں! جنہوں نے کنویں میں پھینکا، غلام بنوایا، سالوں باپ سے جدا کیا — آج وہ سامنے کھڑے ہیں، اور یوسف علیہ السلام کے پاس پوری طاقت ہے۔ پھر بھی نہ بدلہ، نہ طعنہ، نہ شرمندہ کرنا۔ سیرت کی کتابوں میں ہے کہ فتحِ مکہ کے دن نبی ﷺ نے بھی قریش سے یہی الفاظ فرمائے تھے۔"],
 ["n","Fateh-e-Makka par yeh alfaaz seerat ki kitabon (Ibn Ishaq, Sunan-e-Kubra Baihaqi) mein mashhoor hain; sanad mein kuch kalaam hai.","فتحِ مکہ پر یہ الفاظ سیرت کی کتابوں (ابن اسحاق، سنن کبریٰ بیہقی) میں مشہور ہیں؛ سند میں کچھ کلام ہے۔"],

 ["h","Qameez aur lautti hui beenaai","قمیص اور لوٹتی ہوئی بینائی"],
 ["p","Yusuf (AS) ne farmaya: meri yeh qameez le jaao aur abba ke chehre par daal dena, unki beenaai laut aayegi, aur apne sab ghar walon ko lekar mere paas aa jaao. Jaise hi qaafila Misr se chala, Kan'aan mein Yaqub (AS) ne kaha: mujhe Yusuf ki khushbu aa rahi hai — agar tum mujhe sathiya hua na kaho. Ghar walon ne kaha: Allah ki qasam! aap to apni usi purani ghalat-fehmi mein hain. Phir khushkhabri lane wala pahuncha, qameez unke chehre par daali — aur beenaai laut aayi! Farmaya: kya maine tum se nahi kaha tha ki main Allah ki taraf se woh jaanta hoon jo tum nahi jaante?","یوسف علیہ السلام نے فرمایا: میری یہ قمیص لے جاؤ اور ابا کے چہرے پر ڈال دینا، ان کی بینائی لوٹ آئے گی، اور اپنے سب گھر والوں کو لے کر میرے پاس آ جاؤ۔ جیسے ہی قافلہ مصر سے چلا، کنعان میں یعقوب علیہ السلام نے کہا: مجھے یوسف کی خوشبو آ رہی ہے — اگر تم مجھے سٹھیایا ہوا نہ کہو۔ گھر والوں نے کہا: اللہ کی قسم! آپ تو اپنی اسی پرانی غلط فہمی میں ہیں۔ پھر خوشخبری لانے والا پہنچا، قمیص ان کے چہرے پر ڈالی — اور بینائی لوٹ آئی! فرمایا: کیا میں نے تم سے نہیں کہا تھا کہ میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے؟"],
 ["v","12:94-96","Aur jab qaafila (Misr se) chala to unke baap ne kaha: mujhe Yusuf ki khushbu aa rahi hai, agar tum mujhe sathiya hua na samjho. Woh bole: Allah ki qasam! aap to apni usi purani ghalat-fehmi mein hain. Phir jab khushkhabri dene wala aaya to usne woh (qameez) unke chehre par daal di, to woh phir dekhne wale ho gaye. Kaha: kya main ne tum se nahi kaha tha ki main Allah ki taraf se woh jaanta hoon jo tum nahi jaante?","اور جب قافلہ (مصر سے) چلا تو ان کے باپ نے کہا: مجھے یوسف کی خوشبو آ رہی ہے، اگر تم مجھے سٹھیایا ہوا نہ سمجھو۔ وہ بولے: اللہ کی قسم! آپ تو اپنی اسی پرانی غلط فہمی میں ہیں۔ پھر جب خوشخبری دینے والا آیا تو اس نے وہ (قمیص) ان کے چہرے پر ڈال دی، تو وہ پھر دیکھنے والے ہو گئے۔ کہا: کیا میں نے تم سے نہیں کہا تھا کہ میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے؟"],
 ["p","Ek qameez se gham shuru hua tha (jhoote khoon wali), ek qameez se ilzaam saaf hua tha (peeche se phati), aur ek qameez se khushi laut aayi. Bete bhi sharminda ho kar bole: abba! hamare liye maafi ki dua kijiye, hum khatakaar the. Yaqub (AS) ne farmaya: main jald hi apne Rab se tumhare liye maafi maangunga.","ایک قمیص سے غم شروع ہوا تھا (جھوٹے خون والی)، ایک قمیص سے الزام صاف ہوا تھا (پیچھے سے پھٹی)، اور ایک قمیص سے خوشی لوٹ آئی۔ بیٹے بھی شرمندہ ہو کر بولے: ابا! ہمارے لیے معافی کی دعا کیجیے، ہم خطاکار تھے۔ یعقوب علیہ السلام نے فرمایا: میں جلد ہی اپنے رب سے تمہارے لیے معافی مانگوں گا۔"],

 ["h","Khwab sach hua","خواب سچ ہوا"],
 ["p","Poora khandaan Misr pahuncha. Yusuf (AS) ne maa baap ko izzat se apne paas jagah di aur takht par bithaaya. Aur sab — maa baap aur gyarah bhai — unke aage sajde mein gir gaye (us shariat mein ta'zeemi sajda jaaiz tha; hamari shariat mein Allah ke siwa kisi ko sajda haraam hai). Yusuf (AS) ne farmaya: abba jaan! yeh hai mere us purane khwab ki ta'beer — mere Rab ne use sach kar dikhaya.","پورا خاندان مصر پہنچا۔ یوسف علیہ السلام نے ماں باپ کو عزت سے اپنے پاس جگہ دی اور تخت پر بٹھایا۔ اور سب — ماں باپ اور گیارہ بھائی — ان کے آگے سجدے میں گر گئے (اس شریعت میں تعظیمی سجدہ جائز تھا؛ ہماری شریعت میں اللہ کے سوا کسی کو سجدہ حرام ہے)۔ یوسف علیہ السلام نے فرمایا: ابا جان! یہ ہے میرے اس پرانے خواب کی تعبیر — میرے رب نے اسے سچ کر دکھایا۔"],
 ["v","12:100","Aur apne maa baap ko takht par oonchi jagah bithaaya, aur sab unke aage sajde mein gir pade. Aur (Yusuf ne) kaha: abba jaan! yeh mere pehle ke khwab ki ta'beer hai, mere Rab ne use sach kar diya. Aur usne mujh par ehsaan kiya jab mujhe qaid se nikaala, aur aap logon ko dehaat se (yahan) le aaya, is ke baad ki shaitan ne mere aur mere bhaiyon ke darmiyan fasaad daal diya tha. Beshak mera Rab jo chahe uski baareek tadbeer karne wala hai; beshak woh jaanne wala, hikmat wala hai.","اور اپنے ماں باپ کو تخت پر اونچی جگہ بٹھایا، اور سب ان کے آگے سجدے میں گر پڑے۔ اور (یوسف نے) کہا: ابا جان! یہ میرے پہلے کے خواب کی تعبیر ہے، میرے رب نے اسے سچ کر دیا۔ اور اس نے مجھ پر احسان کیا جب مجھے قید سے نکالا، اور آپ لوگوں کو دیہات سے (یہاں) لے آیا، اس کے بعد کہ شیطان نے میرے اور میرے بھائیوں کے درمیان فساد ڈال دیا تھا۔ بے شک میرا رب جو چاہے اس کی باریک تدبیر کرنے والا ہے؛ بے شک وہ جاننے والا، حکمت والا ہے۔"],
 ["p","Akhlaaq ki bulandi dekhiye: 'jab mujhe qaid se nikaala' kaha — 'kuein se nikaala' nahi kaha, taaki bhaiyon ko sharmindagi na ho. Aur saara ilzaam shaitan par daal diya: 'shaitan ne fasaad daala', yeh nahi kaha ki bhaiyon ne zulm kiya. Yeh hai maafi ke baad dil saaf rakhna.","اخلاق کی بلندی دیکھیے: 'جب مجھے قید سے نکالا' کہا — 'کنویں سے نکالا' نہیں کہا، تاکہ بھائیوں کو شرمندگی نہ ہو۔ اور سارا الزام شیطان پر ڈال دیا: 'شیطان نے فساد ڈالا'، یہ نہیں کہا کہ بھائیوں نے ظلم کیا۔ یہ ہے معافی کے بعد دل صاف رکھنا۔"],
 ["h","Bulandi ke waqt ki dua","بلندی کے وقت کی دعا"],
 ["p","Sab kuch mil gaya — taqat, izzat, khandaan, khwab ki ta'beer. Aur is bulandi par Yusuf (AS) ne jo dua ki woh dunya ki nahi, aakhirat ki thi: ae mere Rab! tu ne mujhe hukoomat di aur baaton ki haqeeqat sikhaayi. Ae aasmanon aur zameen ke paida karne wale! tu hi dunya aur aakhirat mein mera kaarsaaz hai. Mujhe islam ki haalat mein maut dena aur mujhe nek logon ke saath mila dena.","سب کچھ مل گیا — طاقت، عزت، خاندان، خواب کی تعبیر۔ اور اس بلندی پر یوسف علیہ السلام نے جو دعا کی وہ دنیا کی نہیں، آخرت کی تھی: اے میرے رب! تو نے مجھے حکومت دی اور باتوں کی حقیقت سکھائی۔ اے آسمانوں اور زمین کے پیدا کرنے والے! تو ہی دنیا اور آخرت میں میرا کارساز ہے۔ مجھے اسلام کی حالت میں موت دینا اور مجھے نیک لوگوں کے ساتھ ملا دینا۔"],
 ["v","12:101","Ae mere Rab! tu ne mujhe hukoomat mein se hissa diya aur mujhe baaton ki haqeeqat sikhaayi. Ae aasmanon aur zameen ke paida karne wale! tu hi dunya aur aakhirat mein mera kaarsaaz hai; mujhe musalman (farmanbardar) ki haalat mein maut de aur mujhe nek logon ke saath mila de.","اے میرے رب! تو نے مجھے حکومت میں سے حصہ دیا اور مجھے باتوں کی حقیقت سکھائی۔ اے آسمانوں اور زمین کے پیدا کرنے والے! تو ہی دنیا اور آخرت میں میرا کارساز ہے؛ مجھے مسلمان (فرمانبردار) کی حالت میں موت دے اور مجھے نیک لوگوں کے ساتھ ملا دے۔"],
 ["v","12:111","Beshak unke qisson mein aql walon ke liye ibrat hai. Yeh koi gadhi hui baat nahi, balki pehle (ki kitabon) ki tasdeeq hai, aur har cheez ki tafseel, aur imaan walon ke liye hidayat aur rehmat hai.","بے شک ان کے قصوں میں عقل والوں کے لیے عبرت ہے۔ یہ کوئی گھڑی ہوئی بات نہیں، بلکہ پہلے (کی کتابوں) کی تصدیق ہے، اور ہر چیز کی تفصیل، اور ایمان والوں کے لیے ہدایت اور رحمت ہے۔"],

 ["h","Is qisse se sabaq","اس قصے سے سبق"],
 ["l",[
  ["Hasad insaan ko sage bhai ke qatl ke mashware tak le jaata hai — hasad se bacho.","حسد انسان کو سگے بھائی کے قتل کے مشورے تک لے جاتا ہے — حسد سے بچو۔"],
  ["'Abhi gunah kar lo, baad mein nek ban jaana' — shaitan ka sab se bada dhoka.","'ابھی گناہ کر لو، بعد میں نیک بن جانا' — شیطان کا سب سے بڑا دھوکا۔"],
  ["Sabr-e-Jameel: rona jaaiz, magar shikayat sirf Allah se — 'innama ashku bassi wa huzni ilallah'.","صبرِ جمیل: رونا جائز، مگر شکایت صرف اللہ سے — 'انما اشکو بثی وحزنی الی اللہ'۔"],
  ["Tanhaai mein gunah ka mauqa ho to 'Ma'aazAllah' — yahi arsh ke saaye ka raasta hai.","تنہائی میں گناہ کا موقع ہو تو 'معاذ اللہ' — یہی عرش کے سائے کا راستہ ہے۔"],
  ["Apni paakbaazi par ghuroor nahi, Allah se madad maango — 'nafs to buraai ka hukm deta hai'.","اپنی پاکبازی پر غرور نہیں، اللہ سے مدد مانگو — 'نفس تو برائی کا حکم دیتا ہے'۔"],
  ["Gunah ke mahol se qaid behtar — deen ke liye takleef qubool karna.","گناہ کے ماحول سے قید بہتر — دین کے لیے تکلیف قبول کرنا۔"],
  ["Har haal mein dawat — qaid khaane mein bhi tauheed ki baat ki.","ہر حال میں دعوت — قید خانے میں بھی توحید کی بات کی۔"],
  ["Apni izzat aur begunahi ki fikr bhi zaroori hai — pehle saaf hua, phir baahar aaye.","اپنی عزت اور بے گناہی کی فکر بھی ضروری ہے — پہلے صاف ہوا، پھر باہر آئے۔"],
  ["Allah ki rehmat se kabhi na-ummeed na ho — barson baad bhi Yusuf mil gaye.","اللہ کی رحمت سے کبھی ناامید نہ ہو — برسوں بعد بھی یوسف مل گئے۔"],
  ["Taqat ho tab bhi maaf kar dena — 'la tathreeba alaikumul yaum'.","طاقت ہو تب بھی معاف کر دینا — 'لا تثریب علیکم الیوم'۔"],
  ["Bulandi par bhi aakhirat ki dua — 'tawaffani musliman wa alhiqni bis-saliheen'.","بلندی پر بھی آخرت کی دعا — 'توفنی مسلما والحقنی بالصالحین'۔"]
 ]]
]}
);
})();
